"use client";

import {useEffect,useId,useRef,useState,useSyncExternalStore,type ReactNode} from 'react';
import type {SpringSave,SpringTarget,SpringTreasureController} from './spring-treasure-state';
import './spring-treasure.css';
import {SPRING_CLUE_STROKES as CLUE_STROKES} from './spring-symbols';

type SymbolName='sun'|'leaf'|'ripple'|'moon'|'flower'|'star'|'heart';
const SYMBOLS:SymbolName[]=['moon','flower','sun','star','leaf','heart','ripple'];
const TITLES:Record<SpringTarget|'satchel',[string,string]>={note:['A note for you','The picnic blanket'],plant:['The money plant','The school desk'],pouch:['A small cloth pouch','The open shelf'],phone:['Before anything else','The school desk'],ticket:['One seat, two people','The shared seat'],tin:['The orange sweet tin','The bus stop'],bench:['The view from here','The lakeside bench'],pocket:['A letter pocket','Beside the forked tree'],lightbox:['Three little drawings','The school desk'],cabinet:['The keepsake cabinet','The school desk'],map:['A hand-drawn map','Two lengths of golden cord'],spade:['The garden spade','The tool rack'],dig:['Recently turned earth','The quiet grove'],box:['The black box','A dry place to sit'],satchel:['Your satchel','Everything you have kept']};

const WORDS={
  opening:['Aami,','I still remember seeing you in my classroom that evening. You were wearing blue, and the sunlight caught your square glasses.','We didn’t know then how things would turn out. I just kept finding reasons to see you.','I’ve put a few things around here that remind me of us. There is a rose-coloured door by the picnic path. Open it from the side facing the blanket, and step into that evening. Find the blue cloth on the front desk.','— Shyamu'],
  plant:['Most of the things you gave me stayed the same. One of them kept growing.','There’s something tucked under its saucer. You won’t need to disturb the plant.'],
  envelope:['Keep this ticket sleeve. The other one is where we shared a single seat.','The pouch on the desk shelf has a few things you’ll need along the way.'],
  phone:['We were in different divisions, but I somehow kept finding my way to you. Then came all those chats.','You were my best friend before I told you how I felt. I was nervous sending that message. Knowing you felt the same still makes me smile.'],
  train:['One seat, the two of us, and Pachai Nirame in our ears. I remember you asking me for a kiss.','I’ve drawn a little of the next stop on these sleeves. Lay one over the other until the seat and the two edge marks match.'],
  tin:['I remember feeding you that orange laddoo on the bus. We were sitting so close, and the wind kept blowing your hair into my face.','There’s a raised drawing under the sweet tray. Take a rubbing of the landmark sketches and the unfinished picture lines beneath them.'],
  lake:['I think about that day by the water quite often. My head in your lap, you patting my head, and the sun on your glasses. I was very happy just staying there.','The rubbing shows three separate landmarks around this lake. Close the drawing, then follow the shore to compare them. The small mark at the forked tree’s roots shows where I left the next envelope.'],
  pocket:['You found the right tree. This is the last drawing.','Take all three back to the light frame on the school desk. Match their corner marks and look at the pictures from left to right.'],
  keepsakes:['The plant, your clip, the candle, your little yellow letter. I still remember all of them.','And this blue hair accessory with the golden thread. I used to hold it close because it smelled like your hair.','I’ve kept the original letter folded. This message is one I wrote for today. The key and map in the parcel are for the last part.'],
  final:['Aami,','I remember small things about us very clearly. What you wore that evening, the orange laddoo, the song on the train, and how it felt to rest in your lap.','Most days I wish I could just sit beside you and tell you about my day. Until I can, I wanted to make you something you could spend a little time in.','You mean a lot to me. I hope you felt some of that while you were here.','There’s a book inside. Get comfortable and take your time.','— Shyamu'],
};

function Note({lines,small=false}:{lines:string[];small?:boolean}){return <div className={`spring-note${small?' spring-note-small':''}`}>{lines.map((line,i)=><p key={i}>{line}</p>)}</div>;}
// The lock and tracing sheets share these exact paths. Three sheets make one
// unambiguous picture; no font, missing glyph or near-matching drawing is involved.

function ClueArtwork({name,sheet}:{name:'sun'|'leaf'|'ripple';sheet?:number}){return <>{CLUE_STROKES[name].flatMap((strokes,index)=>sheet===undefined||sheet===index?strokes.map((d,i)=><path key={`${index}-${i}`} d={d}/>):[])}</>;}
function Icon({name,size=32}:{name:SymbolName;size?:number}){return <svg width={size} height={size} viewBox="0 0 80 80" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{name==='sun'||name==='leaf'||name==='ripple'?<ClueArtwork name={name}/>:name==='moon'?<path d="M52 12a28 28 0 1 0 16 44A27 27 0 0 1 52 12Z"/>:name==='star'?<path d="m40 10 9 20 23 3-17 16 4 23-19-12-20 12 5-23L8 33l23-3Z"/>:name==='heart'?<path d="M40 66 15 41C-1 20 25 7 40 27 55 7 81 20 65 41Z"/>:<><circle cx="40" cy="40" r="8"/>{Array.from({length:5},(_,i)=><ellipse key={i} cx="40" cy="20" rx="9" ry="13" transform={`rotate(${i*72} 40 40)`}/>)}</>}</svg>;}
function ControlIcon({name}:{name:'left'|'right'|'up'|'down'|'turn'|'check'|'key'|'spade'|'cords'}){return <svg className="spring-control-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{name==='check'?<path d="m5 12 4 4L19 6"/>:name==='turn'?<><path d="M5 8a8 8 0 1 1-1 8M5 3v5h5"/></>:name==='key'?<><circle cx="8" cy="8" r="5"/><path d="m11.5 11.5 9 9m-4-4 3-3m-6 0 3-3"/></>:name==='spade'?<><path d="M9 3h6v3a3 3 0 0 1-6 0ZM12 9v8M7 16h10v3l-5 4-5-4Z"/></>:name==='cords'?<><path d="m5 4 15 16M20 4 5 20"/><circle cx="12.5" cy="12" r="4"/></>:<g transform={`rotate(${name==='right'?0:name==='down'?90:name==='left'?180:270} 12 12)`}><path d="M4 12h15m-6-6 6 6-6 6"/></g>}</svg>;}
function Status({children}:{children:ReactNode}){return <p className="spring-status" role="status"><ControlIcon name="check"/>{children}</p>;}
function Action({children,onClick,disabled=false,secondary=false,...rest}:{children:ReactNode;onClick:()=>void;disabled?:boolean;secondary?:boolean;'aria-label'?:string}){return <button type="button" className={`spring-action${secondary?' spring-action-secondary':''}`} onClick={onClick} disabled={disabled} {...rest}>{children}</button>;}

function Registration(){return <g className="spring-registration" fill="none" stroke="currentColor" strokeWidth="2"><path d="M22 36V20h19M378 184v16h-19M22 173v27h10M365 20h13v7"/><circle cx="30" cy="28" r="2" fill="currentColor"/><path d="m370 192 4-4 4 4"/></g>;}

/** Authored fragments physically form three pictures when all paper registrations meet. */
function SymbolFragments({sheet}:{sheet:number}){return <g fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round">{(['sun','leaf','ripple'] as const).map((name,i)=><g key={name} transform={`translate(${40+i*120} 70)`}><ClueArtwork name={name} sheet={sheet}/></g>)}</g>;}

function LandscapeSketch({mark=false}:{mark?:boolean}){return <svg className="spring-landscape" viewBox="0 0 500 270" role="img" aria-label="Three separate field sketches of landmarks around the lake: the forked cherry tree with a letter pocket at its roots, the little footbridge, and paired stones. These are individual sketches, not a panorama.">
  <text x="250" y="20" textAnchor="middle" fill="currentColor" fontSize="10" letterSpacing="2">LANDMARKS AROUND THE LAKE</text>
  <g fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="12" y="35" width="190" height="208" rx="3" strokeOpacity=".25"/><rect x="216" y="35" width="272" height="97" rx="3" strokeOpacity=".25"/><rect x="216" y="146" width="272" height="97" rx="3" strokeOpacity=".25"/>
    <path d="M85 198l4-90-21-31m20 51 31-54m-35 68-33-26m43-8 30-19M77 199l-20 8m30-9 25 8M44 210q52 9 114 0"/>
    <path d="M42 94q-19-31 10-37 4-27 31-15 30-8 36 14 30 5 22 31-8 18-30 12-12 18-35 3-25 7-34-8Z"/>
    <path d="m105 191 18-3 3 13-18 3Z" strokeDasharray={mark?undefined:'3 3'}/>
    {mark&&<><circle cx="115" cy="196" r="21" stroke="#9b542c"/><path d="m137 190 21-12" stroke="#9b542c"/></>}
    <path d="M271 99h156m-150-13h145m-145-21v40m36-40v40m36-40v40m36-40v40m36-40v40M267 65h163m-152 48q29-8 53 0t49 0t49 0"/>
    <path d="M305 215q-17-37 8-43 28-5 33 42Zm43 0q-8-47 20-43 28 5 31 43ZM279 222q52 6 148 0"/>
  </g>
  <g textAnchor="middle" fontSize="11" fill="currentColor"><text x="107" y="229">Forked tree · letter at the roots</text><text x="352" y="53">Little footbridge</text><text x="352" y="162">Two stones standing together</text></g>
  <text x="250" y="263" textAnchor="middle" fill="currentColor" fontSize="10">Close the drawing, then follow the shore to find each landmark</text>
</svg>;}
function CollectedDrawing({sheet}:{sheet:number}){return <details className="spring-sketch-details"><summary>Look at drawing {'ABC'[sheet]}’s picture fragments</summary><svg className="spring-fragment-preview" viewBox="0 0 400 220" role="img" aria-label={`Drawing ${'ABC'[sheet]}: incomplete picture lines and matching corner marks for the desk light frame.`}><Registration/><SymbolFragments sheet={sheet}/></svg><p className="spring-aside">These unfinished lines belong on the light frame at the school desk. The other drawings complete them.</p></details>;}

function TicketPuzzle({state,controller}:{state:SpringSave;controller:SpringTreasureController}){
  const [x,setX]=useState(state.ticketSolved?0:1),[y,setY]=useState(state.ticketSolved?0:-1),[turn,setTurn]=useState(state.ticketSolved?0:1);
  const grainId=useId();
  const [held,setHeld]=useState(false);const pointer=useRef<{x:number;y:number}|null>(null);
  const aligned=x===0&&y===0&&turn===0;
  const move=(dx:number,dy:number)=>{setX(v=>Math.max(-2,Math.min(2,v+dx)));setY(v=>Math.max(-2,Math.min(2,v+dy)));};
  return <div className="spring-puzzle-layout"><div><Note lines={WORDS.train} small/>{!state.ticketFound?<><p className="spring-object-description">A paper sleeve is tucked into the seat-back pocket.</p><Action onClick={()=>controller.act('take-ticket')}>Take the second ticket sleeve</Action></>:<Status>Second sleeve kept safely.</Status>}{!state.plantFound&&<p className="spring-aside">The matching sleeve is beneath the plant saucer on the school desk. Bring both here to compare them.</p>}</div>
    <div className="spring-workspace"><div className="spring-workspace-label">{state.ticketSolved?'Drawing A · kept in your satchel':'Match the seat and the two different corner marks'}</div>
    <div className={`spring-ticket-table${held?' spring-is-dragging':''}`} onPointerDown={event=>{if(!state.ticketFound||!state.plantFound||state.ticketSolved)return;pointer.current={x:event.clientX,y:event.clientY};event.currentTarget.setPointerCapture(event.pointerId);setHeld(true);}} onPointerUp={event=>{if(!pointer.current)return;const dx=event.clientX-pointer.current.x,dy=event.clientY-pointer.current.y;move(Math.round(dx/45),Math.round(dy/45));pointer.current=null;setHeld(false);}} onPointerCancel={()=>{pointer.current=null;setHeld(false);}}>
      <svg viewBox="0 0 420 300" aria-label="Overlapping ticket sleeves. Match the two halves of the seat outline and both corner marks." role="img"><defs><pattern id={grainId} width="7" height="7" patternUnits="userSpaceOnUse"><circle cx="2" cy="4" r=".35" fill="#624b35" opacity=".1"/></pattern></defs><g transform="translate(20 40)"><rect width="380" height="220" rx="4" fill="#e4d8bf" stroke="#9e8b69"/><rect width="380" height="220" rx="4" fill={`url(#${grainId})`}/><g stroke="#665b45" fill="none" strokeWidth="2.5"><path d="M190 56h-44q-14 0-14 14v78h58M132 130h58M132 148l-7 36"/><path d="M22 37V20h19M358 184v16h-19"/><circle cx="30" cy="28" r="2" fill="#665b45"/><path d="m350 192 4-4 4 4"/></g><text x="20" y="211" fontSize="9" fill="#806f52" letterSpacing="2">ONE SEAT</text></g>
      {state.ticketFound&&state.plantFound&&<g transform={`translate(${20+x*32} ${40+y*26}) rotate(${turn*90} 190 110)`} className="spring-moving-paper"><rect width="380" height="220" rx="4" fill="#f5ecd8" fillOpacity=".4" stroke="#9b734b" strokeDasharray="4 3"/><g stroke="#6b563b" fill="none" strokeWidth="2.5"><path d="M190 56h44q14 0 14 14v78h-58M190 130h58M248 148l7 36"/><path d="M22 37V20h19M358 184v16h-19"/><circle cx="30" cy="28" r="2" fill="#6b563b"/><path d="m350 192 4-4 4 4"/></g><path d="M38 75h55v55H38Zm250 0h55v55h-55Z" fill="#f9f2de" stroke="#a58b66"/><g transform="translate(42 90)" stroke="#72614b" fill="none"><path d="m0 0 21-13L42 0M5 0v25m32-25v25M3 12h36m-32 13h26"/></g><g transform="translate(293 88)" stroke="#aa682f" fill="none"><ellipse cx="21" cy="12" rx="19" ry="8"/><path d="M2 12v16q19 12 38 0V12"/><circle cx="18" cy="11" r="4"/></g></g>}
      {aligned&&state.ticketFound&&state.plantFound&&<path d="m375 274 6 6 13-15" fill="none" stroke="#527146" strokeWidth="3"/>}</svg>
    </div>
    {!state.ticketSolved&&state.ticketFound&&state.plantFound&&<><PaperControls onMove={move} onTurn={()=>setTurn(v=>(v+1)%4)}/><p className="spring-active-paper" role="status">{aligned?'Both corners match · ready to fold':turn?`Top sleeve turned ${turn*90}° · turn it upright`:'Top sleeve upright · match both corner marks'}</p><p className="spring-gesture-note">Use the arrows to move one step, or drag and release. The dotted upper corner and arrow lower corner must both overlap.</p><Action disabled={!aligned} onClick={()=>controller.act('align-tickets',{x,y,turn})}>Fold the sleeves together</Action></>}
    {state.ticketSolved&&<><Status>The windows show a bus shelter and an orange sweet tin.</Status><p className="spring-aside">Drawing A is in your satchel. The folded tabs keep the two sleeves together. Picture fragments are printed on the reverse.</p><CollectedDrawing sheet={0}/></>}
    </div></div>;
}

function PaperControls({onMove,onTurn}:{onMove:(x:number,y:number)=>void;onTurn:()=>void}){return <div className="spring-paper-controls"><div className="spring-arrow-pad">{([['left',-1,0],['up',0,-1],['down',0,1],['right',1,0]] as const).map(([direction,x,y])=><button type="button" key={direction} aria-label={`Move paper ${direction} one step`} onClick={()=>onMove(x,y)}><ControlIcon name={direction}/></button>)}</div><button type="button" className="spring-turn-button" onClick={onTurn}><ControlIcon name="turn"/><span>Turn 90°</span></button></div>;}

function TinPuzzle({state,controller}:{state:SpringSave;controller:SpringTreasureController}){
  const [open,setOpen]=useState(state.paperPlaced),[tray,setTray]=useState(state.paperPlaced),[rubs,setRubs]=useState(state.rubbingDone?5:0);
  const rubCount=useRef(rubs),stroke=useRef<{x:number;y:number;pointerId:number}|null>(null);
  const rub=()=>{if(!state.paperClipped||state.rubbingDone||rubCount.current===5)return;const next=++rubCount.current;setRubs(next);if(next===5)controller.act('rub-paper');};
  return <div className="spring-puzzle-layout"><div><Note lines={WORDS.tin} small/><ol className="spring-tool-steps"><li className={state.paperPlaced?'spring-step-done':''}>Lay the tracing paper over the plate.</li><li className={state.paperClipped?'spring-step-done':''}>Hold it against the breeze with your hair clip.</li><li className={state.rubbingDone?'spring-step-done':''}>Use the side of the pencil to pick up the drawing.</li></ol></div><div className="spring-workspace">
    <div className={`spring-tin-art${open?' is-open':''}${tray?' tray-lifted':''}`}><div className="spring-tin-lid"><span>A little something<br/>for the journey</span></div><div className="spring-tin-base">{!tray?<div className="spring-sweets">{Array.from({length:5},(_,i)=><i key={i}/>)}</div>:<div className={`spring-rubbing${state.paperPlaced?' has-paper':''}`} onPointerDown={event=>{if(!state.paperClipped||state.rubbingDone||!event.isPrimary||event.button!==0)return;stroke.current={x:event.clientX,y:event.clientY,pointerId:event.pointerId};event.currentTarget.setPointerCapture(event.pointerId);rub();}} onPointerUp={()=>{stroke.current=null;}} onPointerCancel={()=>{stroke.current=null;}} onLostPointerCapture={()=>{stroke.current=null;}} onPointerMove={event=>{const previous=stroke.current;if(!previous||previous.pointerId!==event.pointerId||Math.hypot(event.clientX-previous.x,event.clientY-previous.y)<18)return;stroke.current={x:event.clientX,y:event.clientY,pointerId:event.pointerId};rub();}}><div style={{opacity:state.rubbingDone?1:Math.min(.08+rubs*.19,1)}}><LandscapeSketch/></div>{state.paperClipped&&<span className="spring-paper-clip" aria-label="Hair clip holding the paper"/>}</div>}</div></div>
    <div className="spring-actions">{!open?<Action onClick={()=>setOpen(true)}>Lift the tin lid</Action>:!tray?<Action onClick={()=>setTray(true)}>Lift out the sweet tray</Action>:!state.pouchTaken?<p className="spring-aside">The raised lines need paper and a pencil. Check the pouch on the school desk’s shelf.</p>:!state.paperPlaced?<Action onClick={()=>controller.act('place-paper')}>Lay down the tracing paper</Action>:!state.paperClipped?<Action onClick={()=>controller.act('clip-paper')}>Secure the paper with the hair clip</Action>:!state.rubbingDone?<><Action onClick={rub}>Rub with the pencil · {rubs}/5</Action><p className="spring-gesture-note">Make a few strokes over the paper, or tap the pencil button.</p></>:<Status>Drawing B is safely in your satchel. The clip and pencil are back in the pouch.</Status>}</div>
    {state.rubbingDone&&<><CollectedDrawing sheet={1}/><p className="spring-aside">Take Drawing B to the lakeside bench to compare these landmarks. The forked tree, little footbridge and paired stones are separate sketches around the lake; the tree’s roots are marked.</p></>}
  </div></div>;
}

type SheetPosition={x:number;y:number;turn:number};
const FRAME_SAVE_KEY='between-spring-light-frame-v1';
function LightFrame({state}:{state:SpringSave}){
  const available=[state.ticketSolved,state.rubbingDone,state.pocketFound];
  const fresh=()=>({placed:[false,false,false],positions:[{x:1,y:0,turn:1},{x:0,y:-1,turn:3},{x:-1,y:1,turn:2}]});
  const [papers,setPapers]=useState<{placed:boolean[];positions:SheetPosition[]}>(()=>{
    try{
      const saved=JSON.parse(localStorage.getItem(FRAME_SAVE_KEY)||'null');
      if(saved?.positions?.length===3&&saved?.placed?.length===3&&saved.positions.every((p:SheetPosition)=>Number.isInteger(p.x)&&Math.abs(p.x)<=2&&Number.isInteger(p.y)&&Math.abs(p.y)<=2&&Number.isInteger(p.turn)&&p.turn>=0&&p.turn<4))return {positions:saved.positions,placed:saved.placed.map((value:boolean,i:number)=>value===true&&available[i])};
    }catch{/* The puzzle also works when browser storage is unavailable. */}
    return fresh();
  });
  const [active,setActive]=useState(available.findIndex(Boolean)<0?0:available.findIndex(Boolean));
  const {placed,positions}=papers;
  const aligned=(i:number)=>placed[i]&&positions[i].x===0&&positions[i].y===0&&positions[i].turn===0;
  const complete=positions.every((_,i)=>aligned(i));
  useEffect(()=>{try{localStorage.setItem(FRAME_SAVE_KEY,JSON.stringify(papers));}catch{/* Keep the current inspection playable. */}},[papers]);
  const adjust=(dx:number,dy:number)=>setPapers(old=>({...old,positions:old.positions.map((p,i)=>i===active?{...p,x:Math.max(-2,Math.min(2,p.x+dx)),y:Math.max(-2,Math.min(2,p.y+dy))}:p)}));
  const pointer=useRef<{x:number;y:number}|null>(null);
  return <div className="spring-puzzle-layout"><div>
    <Note lines={['Each drawing carries part of three pictures. Place A, B and C on the frame, one at a time.','Turn each sheet upright. Move its dotted corner and arrow corner onto the matching marks fixed to the frame.','Read the completed pictures from left to right for the cabinet’s setting.']} small/>
    <div className="spring-sheet-tabs" aria-label="Choose a drawing">{['A · Shared seat','B · Lakeside','C · Tree pocket'].map((name,i)=><button type="button" key={name} disabled={!available[i]} className={active===i?'is-active':''} aria-pressed={active===i} onClick={()=>{setActive(i);setPapers(old=>({...old,placed:old.placed.map((v,j)=>j===i?true:v)}));}}><span>{name}</span><small>{!available[i]?'Still to find':aligned(i)?'Corners matched':placed[i]?'On the frame':'Place this sheet'}</small></button>)}</div>
    {!available.every(Boolean)&&<p className="spring-aside">{!available[0]?'A comes from fitting the two ticket sleeves together.':!available[1]?'B is the pencil rubbing from the sweet tin.':'C is in the letter pocket at the forked tree roots.'} You can return with it; your work here is saved.</p>}
  </div><div className="spring-workspace"><div className="spring-workspace-label">{complete?'All three drawings line up':'Match each sheet to the fixed frame corners'}</div>
    <div className="spring-light-frame" onPointerDown={event=>{if(!placed[active]||complete)return;pointer.current={x:event.clientX,y:event.clientY};event.currentTarget.setPointerCapture(event.pointerId);}} onPointerUp={event=>{if(!pointer.current)return;adjust(Math.round((event.clientX-pointer.current.x)/45),Math.round((event.clientY-pointer.current.y)/45));pointer.current=null;}} onPointerCancel={()=>{pointer.current=null;}}>
      <svg viewBox="-18 -14 436 248" role="img" aria-label={complete?'Three complete pictures, left to right: sun, leaf, ripple.':'A fixed frame with a dotted upper left corner and an arrow in the lower right corner. Move each sheet onto those corners.'}>
        <rect x="7" y="7" width="386" height="206" rx="3" fill="#faf2d6" fillOpacity=".6" stroke="#687659" strokeWidth="1.5"/>
        <g className="spring-frame-target" color="#536846"><Registration/></g><text x="200" y="28" textAnchor="middle" fontSize="9" fill="#687659" letterSpacing="2">TOP OF FRAME</text>
        {positions.map((p,i)=>placed[i]&&<g key={i} transform={`translate(${p.x*18} ${p.y*14}) rotate(${p.turn*90} 200 110)`} className="spring-moving-paper" opacity={active===i||complete?1:.45} style={{color:complete?'#405139':['#6f5b3d','#536349','#776145'][i]}}><rect x="7" y="7" width="386" height="206" fill="transparent" stroke={active===i&&!complete?'#aa743a':'#c5bba0'} strokeWidth={active===i&&!complete?1.2:.6}/><Registration/><SymbolFragments sheet={i}/><text x="200" y="192" textAnchor="middle" fontSize="10" fill="currentColor">{!complete?`DRAWING ${'ABC'[i]} · TOP`:''}</text></g>)}
      </svg>
    </div>
    {placed[active]&&!complete&&<><p className="spring-active-paper" role="status">Drawing {'ABC'[active]} · {aligned(active)?'corners matched':positions[active].turn!==0?`turned ${positions[active].turn*90}° · turn it upright`:'upright · move its corners onto the frame marks'}</p><PaperControls onMove={adjust} onTurn={()=>setPapers(old=>({...old,positions:old.positions.map((p,i)=>i===active?{...p,turn:(p.turn+1)%4}:p)}))}/></>}
    {complete?<><Status>Read the pictures in this order.</Status><div className="spring-symbol-answer" aria-label="Cabinet setting: sun, leaf, ripple">{(['sun','leaf','ripple'] as const).map((name,i)=><div key={name}><small>{i+1}</small><Icon name={name}/><span>{name}</span></div>)}</div><p className="spring-aside">Set these pictures on the cabinet beside the frame. This completed drawing stays here when you return.</p></>:<p className="spring-gesture-note">Select a sheet above. Use the arrows to move one step, or drag and release. “Corners matched” confirms each sheet is in place.</p>}
  </div></div>;
}

function Cabinet({state,controller}:{state:SpringSave;controller:SpringTreasureController}){
  const [wheels,setWheels]=useState([0,0,0]),[message,setMessage]=useState('');
  const change=(index:number,by:number)=>setWheels(old=>old.map((v,i)=>i===index?(v+by+SYMBOLS.length)%SYMBOLS.length:v));
  return state.cabinetOpen?<div className="spring-puzzle-layout"><div><div className="spring-keepsake-art" aria-label="Sky-blue round hair accessory with its original golden wrapping, beside a folded yellow letter"><div className="spring-blue-keepsake"/><div className="spring-yellow-letter">Kept safe</div><div className="spring-brass-key"/></div><Status>The catch is open. The key, map and separate tracing cords are in your satchel.</Status></div><div><Note lines={WORDS.keepsakes}/><Action onClick={()=>{controller.act('read-keepsakes');setMessage('You can open the map from your satchel whenever you need it.');}}>Read the new message and keep the parcel</Action><p className="spring-aside" role="status">{message||'The blue accessory and its original golden wrapping stay together.'}</p></div></div>:<div className="spring-puzzle-layout"><div><Note lines={['I made this cabinet for the things you gave me.','The three drawings fit together on the light frame beside it. The pictures show the setting for these wheels.']} small/><p className="spring-aside">Turn the wheels, then try the catch. The setting reads left to right.</p></div><div className="spring-workspace spring-cabinet-workspace"><div className="spring-cabinet-face"><div className="spring-lock-wheels">{wheels.map((index,i)=><div className="spring-lock-wheel" key={i}><button type="button" onClick={()=>change(i,-1)} aria-label={`Previous symbol on wheel ${i+1}`}><ControlIcon name="up"/></button><span className="spring-wheel-symbol" aria-live="polite"><Icon name={SYMBOLS[index]} size={54}/><small>{SYMBOLS[index]}</small></span><button type="button" onClick={()=>change(i,1)} aria-label={`Next symbol on wheel ${i+1}`}><ControlIcon name="down"/></button></div>)}</div><button type="button" className="spring-catch" onClick={()=>{const ok=controller.act('open-cabinet',wheels.map(i=>SYMBOLS[i]));setMessage(ok?'The catch slides free.':'The catch stays in place. Try another setting.');}}>Slide the brass catch</button></div><p className="spring-feedback" role="status">{message||'Three symbol wheels. A small brass catch.'}</p></div></div>;
}

type MapPin='tree'|'marker'|'bridge'|'boulders'|'desk'|'seat'|'bus'|'tools';
const PINS:{id:MapPin;label:string;x:number;y:number;shape:string}[]=[{id:'tree',label:'Forked cherry tree',x:264,y:184,shape:'tree'},{id:'marker',label:'Low stone marker',x:381,y:184,shape:'stone'},{id:'bridge',label:'Little footbridge',x:327,y:76,shape:'bridge'},{id:'boulders',label:'Paired boulders',x:327,y:238,shape:'pair'},{id:'desk',label:'School desk',x:30,y:30,shape:'house'},{id:'seat',label:'Shared seat',x:35,y:100,shape:'seat'},{id:'bus',label:'Bus stop',x:76,y:197,shape:'house'},{id:'tools',label:'Garden rack',x:174,y:220,shape:'tools'}];
function MapDrawing({lines,selected,onPin}:{lines:[boolean,boolean];selected:MapPin|null;onPin?:(pin:MapPin)=>void}){
  const activate=(pin:MapPin)=>onPin?.(pin);
  return <svg className="spring-map-drawing" viewBox="0 0 440 288" role="group" aria-label="Map of the grove. Select the two landmarks named in each instruction to stretch a cord between them."><g fill="none" stroke="#b0a482" strokeWidth="1.4"><path d="M20 10q60-10 100 12t130-4q120-12 170 35l-10 200q-95 31-158 7T30 244Z" strokeDasharray="3 7"/><path d="M33 30q34 25 2 70t41 97q42 43 98 23t91-25q57-37 67-92M35 100q100 65 187 37t110-34" strokeDasharray="4 5"/><path d="M245 100q-20-35 14-49 22-13 46 3t36 42q-12 39-44 44-38-1-52-40Z" fill="#adbfad" fillOpacity=".35"/><path d="M255 91q20-13 48 1m-44 10 45 3" stroke="#8caa9c"/></g><text x="19" y="274" fontSize="10" fill="#8c7958" letterSpacing="2">THE SPRING GROVE</text><g fill="none" stroke="#b48a3f" strokeWidth="2.5">{lines[0]&&<path d="M246 184H400"/>}{lines[1]&&<path d="M327 55V257"/>}</g>{lines[0]&&lines[1]&&<><circle cx="327" cy="184" r="12" fill="none" stroke="#a46f35" strokeWidth="1.7"/><text x="342" y="175" fontSize="10" fill="#8f5f30">the crossing</text></>}
    {PINS.map(pin=><g key={pin.id} role={onPin?'button':undefined} tabIndex={onPin?0:undefined} aria-label={pin.label} aria-pressed={selected===pin.id} className={`spring-map-pin${selected===pin.id?' is-selected':''}`} transform={`translate(${pin.x} ${pin.y})`} onClick={()=>activate(pin.id)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();activate(pin.id);}}}><title>{pin.label}</title><circle r="24" fill={selected===pin.id?'#dfcc96':'#f2e8ce'} fillOpacity=".78" stroke={selected===pin.id?'#aa7636':'transparent'}/><g fill="none" stroke="#58604a" strokeWidth="1.7" strokeLinecap="round">{pin.shape==='tree'?<><path d="M0 13V-4L-7-12M0 0l8-12M-8 13h16"/><circle cx="-5" cy="-10" r="8"/><circle cx="6" cy="-11" r="8"/></>:pin.shape==='bridge'?<><path d="M-16-2h32M-16 7h32m-13-15v18M0-8v18m13-18v18"/></>:pin.shape==='stone'?<path d="M-11 8q-2-21 10-17 14 0 14 17Z"/>:pin.shape==='pair'?<><path d="M-16 9q-4-17 6-19 12-2 11 19Z"/><path d="M1 9q-4-24 8-19 11 4 9 19Z"/></>:pin.shape==='seat'?<path d="M-13-12v18h26V-9H0v15m-9 0-2 9m20-9 2 9"/>:pin.shape==='tools'?<path d="M-7-14V7l-4 3 4 7 5-7-5-3m12-21v24m-4-5h9"/>:<path d="m-17-3 17-10L17-3M-12-1v15m24-15v15M-14 10h28"/>}</g><text y={pin.id==='boulders'?32:-27} textAnchor="middle" fontSize="9.5" fill="#655b43">{pin.id==='tree'?'Forked tree':pin.id==='marker'?'Low stone':pin.id==='bridge'?'Footbridge':pin.id==='boulders'?'Paired stones':pin.label}</text></g>)}
  </svg>;
}

function MapPuzzle({state,controller}:{state:SpringSave;controller:SpringTreasureController}){
  const [pin,setPin]=useState<MapPin|null>(null),[feedback,setFeedback]=useState('');
  if(!state.cabinetOpen)return <><Note lines={['The map is inside the keepsake cabinet on the school desk.']} small/><p className="spring-aside">The cabinet’s three symbol wheels open with the setting shown by your drawings.</p></>;
  const choose=(next:MapPin)=>{if(!pin){setPin(next);setFeedback(`Cord held at ${PINS.find(p=>p.id===next)?.label.toLowerCase()}. Choose its partner.`);return;}if(next===pin){setPin(null);setFeedback('Cord released.');return;}const ok=controller.act('map-line',[pin,next]);setFeedback(ok?'The cord follows a straight line through these landmarks.':'Those landmarks don’t form either pair in the instructions. Try another pair.');setPin(null);};
  return <div className="spring-puzzle-layout"><div><Note lines={['Stretch one cord from the forked cherry tree through the low stone marker.','Stretch the other from the footbridge through the two stones that stand together.','Where the lines cross is where I left the box. There’s a spade in the garden rack.']} small/><p className="spring-aside">Tap one landmark, then its partner, on the map or the named buttons below it. Tap the same landmark again to release the cord. The separate cords came with the map; the golden thread on your keepsake stays wrapped.</p><ul className="spring-map-pairs" aria-label="Cords placed"><li>{state.mapLines[0]?<ControlIcon name="check"/>:<span>1</span>}<span>Forked tree to low stone {state.mapLines[0]?'· cord placed':''}</span></li><li>{state.mapLines[1]?<ControlIcon name="check"/>:<span>2</span>}<span>Footbridge to paired stones {state.mapLines[1]?'· cord placed':''}</span></li></ul>{state.mapLines.every(Boolean)&&<Status>The crossing lies beyond the lake, east of the garden rack. Look for the turned earth between the four landmarks.</Status>}</div><div className="spring-workspace spring-map-paper"><MapDrawing lines={state.mapLines} selected={pin} onPin={choose}/><div className="spring-map-landmarks" aria-label="Choose cord landmarks">{PINS.filter(p=>['tree','marker','bridge','boulders'].includes(p.id)).map(p=><button type="button" key={p.id} aria-pressed={pin===p.id} onClick={()=>choose(p.id)}>{p.label}</button>)}</div><p className="spring-feedback" role="status">{feedback||'Two cords, two pairs of landmarks.'}</p></div></div>;
}

function DigPuzzle({state,controller}:{state:SpringSave;controller:SpringTreasureController}){
  const [busy,setBusy]=useState(false),timer=useRef<ReturnType<typeof setTimeout>|null>(null);
  useEffect(()=>()=>{if(timer.current)clearTimeout(timer.current);},[]);
  return <div className="spring-puzzle-layout"><div><p className="spring-object-description">The soil here is darker and a little loose. There are small clumps beside the patch.</p>{!state.spadeTaken?<><Note lines={['You could move this soil with a garden spade. There’s one standing in the tool rack.']} small/><p className="spring-aside">The earth stays as you found it. You can come back with the spade.</p></>:state.digStage<3?<><Note lines={['The box is only a little way down. Loosen the soil carefully, then clear the lid.']} small/><Action disabled={busy} onClick={()=>{setBusy(true);controller.act('dig');timer.current=setTimeout(()=>setBusy(false),1000);}}>{busy?'Moving the soil…':['Loosen the topsoil','Clear the black lid','Lift out the box'][state.digStage]}</Action></>:<Status>The box is out of the soil, on a dry stand beside the patch.</Status>}</div><div className={`spring-dig-art spring-dig-stage-${state.digStage}${busy?' is-digging':''}`} aria-label={`Excavation: ${['undisturbed soil','loosened soil','box lid exposed','box recovered'][state.digStage]}`}><div className="spring-soil-mound"/><div className="spring-dug-hole"/>{state.digStage>0&&<div className="spring-buried-box"><span/></div>}{busy&&<div className="spring-spade-silhouette"/>}<span className="spring-dig-caption">{['Damp, recently turned earth','The topsoil has loosened','A black lid beneath the soil','Recovered carefully'][state.digStage]}</span></div></div>;
}

function BoxPuzzle({state,controller,onReadBook}:{state:SpringSave;controller:SpringTreasureController;onReadBook:()=>boolean}){
  const [inserted,setInserted]=useState(false),[turned,setTurned]=useState(false),[bookFeedback,setBookFeedback]=useState('');
  if(state.digStage<3)return <Note lines={['The box is still beneath the soil. A garden spade will help you lift it out.']} small/>;
  return <div className="spring-puzzle-layout"><div><div className={`spring-box-art${state.boxOpen?' is-open':''}${inserted?' has-key':''}`}><div className="spring-box-lid"/><div className="spring-box-body"><i/>{state.boxOpen?<span className="spring-book-art">SPRING<br/><small>for Aami</small></span>:inserted&&<span className="spring-inserted-key"/>}</div></div>{!state.boxOpen&&<p className="spring-aside">The outside is still muddy. The brass lock is clean enough to turn.</p>}{!state.cabinetOpen?<Note lines={['There’s a lock on the lid. You’ll need the brass key from the keepsake cabinet.']} small/>:!state.boxOpen?<div className="spring-actions">{!inserted?<Action onClick={()=>setInserted(true)}>Insert the brass key</Action>:!turned?<Action onClick={()=>setTurned(true)}>Turn the key</Action>:<Action onClick={()=>controller.act('open-box')}>Lift the lid</Action>}</div>:<Status>The book is dry inside its wrap.</Status>}</div><div>{state.boxOpen?<><Note lines={WORDS.final}/><Action onClick={()=>{controller.act('take-book');if(!onReadBook())setBookFeedback('Set down the object you are carrying on a clear patch of ground, then open the book.');}}>Open the Spring book</Action>{bookFeedback&&<p className="spring-feedback" role="status">{bookFeedback}</p>}</>:<p className="spring-object-description">A shallow black box, just large enough for a book. It has a brass catch and a hinged lid.</p>}</div></div>;
}

function Satchel({state,controller,onReadBook}:{state:SpringSave;controller:SpringTreasureController;onReadBook:()=>boolean}){
  const [tab,setTab]=useState<'objects'|'journal'|'map'>('objects'),[journal,setJournal]=useState(0),[confirmReset,setConfirmReset]=useState(false),[bookFeedback,setBookFeedback]=useState('');
  const objects:{title:string;detail:string;show:boolean;art:ReactNode}[]=[
    {title:state.ticketSolved?'Drawing A':'First ticket sleeve',detail:state.ticketSolved?'The two sleeves, folded together. A bus stop and orange tin show through the windows; picture fragments are on the reverse.':'From beneath the plant saucer. It has clear windows and half a seat drawn on it.',show:state.plantFound,art:<span className="spring-inventory-paper">{state.ticketSolved?'A':'½'}</span>},
    {title:'Second ticket sleeve',detail:'Found in the shared-seat pocket. It belongs with the first sleeve.',show:state.ticketFound&&!state.ticketSolved,art:<span className="spring-inventory-paper">½</span>},
    {title:'Clip, pencil and paper',detail:'From the pouch on the desk shelf. They stay safely together after use.',show:state.pouchTaken,art:<span className="spring-inventory-pencil"/>},
    {title:'Drawing B',detail:'The rubbing from the tin. Separate lakeside sketches, with the letter pocket marked at the forked tree’s roots.',show:state.rubbingDone,art:<span className="spring-inventory-paper">B</span>},
    {title:'Drawing C',detail:'The last sheet, from the tree pocket. All three sheets carry unfinished picture lines for the desk’s light frame.',show:state.pocketFound,art:<span className="spring-inventory-paper">C</span>},
    {title:'Brass key',detail:state.boxOpen?'Used to open the black box.':'Kept with the map in the cabinet. A small key for the black box.',show:state.cabinetOpen,art:<span className="spring-inventory-key"><ControlIcon name="key"/></span>},
    {title:'Map and tracing cords',detail:'A drawing of this grove. The two cord lines meet where the box is buried.',show:state.cabinetOpen,art:<span className="spring-inventory-paper"><ControlIcon name="cords"/></span>},
    {title:'Garden spade',detail:'From the garden rack. The blade has a little soil on it.',show:state.spadeTaken,art:<span className="spring-inventory-spade"><ControlIcon name="spade"/></span>},
  ];
  const notes=[{title:'The first note',lines:WORDS.opening,show:state.noteRead},{title:'Under the saucer',lines:WORDS.envelope,show:state.plantFound},{title:'The phone',lines:WORDS.phone,show:state.phoneRead},{title:'The shared seat',lines:WORDS.train,show:state.ticketFound},{title:'The sweet tin',lines:WORDS.tin,show:state.rubbingDone},{title:'By the water',lines:WORDS.lake,show:state.benchVisited},{title:'The tree pocket',lines:WORDS.pocket,show:state.pocketFound},{title:'The keepsakes',lines:WORDS.keepsakes,show:state.keepsakeRead},{title:'Inside the box',lines:WORDS.final,show:state.boxOpen}].filter(note=>note.show);
  return <><div className="spring-satchel-tabs" role="tablist" aria-label="Satchel sections">{(['objects','journal','map'] as const).map(name=><button type="button" key={name} role="tab" aria-selected={tab===name} onClick={()=>setTab(name)} disabled={name==='map'&&!state.cabinetOpen}>{name==='objects'?'Kept objects':name==='journal'?'Read again':'Map'}</button>)}</div>
  {tab==='objects'?<>{objects.some(o=>o.show)?<div className="spring-inventory-grid">{objects.filter(o=>o.show).map(object=><article key={object.title} className="spring-inventory-item"><div className="spring-inventory-art">{object.art}</div><div><h3>{object.title}</h3><p>{object.detail}</p></div></article>)}</div>:<div className="spring-empty-satchel"><p>Room for the little things you find.</p><span>The note on the picnic blanket is a good place to start.</span></div>}{state.rubbingDone&&<details className="spring-sketch-details"><summary>Look at the lakeside rubbing</summary><LandscapeSketch mark={state.benchVisited}/></details>}{state.ticketSolved&&<CollectedDrawing sheet={0}/>}{state.rubbingDone&&<CollectedDrawing sheet={1}/>}{state.pocketFound&&<CollectedDrawing sheet={2}/>}{state.bookFound&&<div className="spring-actions"><Action onClick={()=>{if(!onReadBook())setBookFeedback('Set down the object you are carrying on a clear patch of ground, then open the book.');}}>Read Spring again</Action>{bookFeedback&&<p className="spring-feedback" role="status">{bookFeedback}</p>}</div>}</>:tab==='journal'?<div className="spring-journal">{notes.length?<><div className="spring-journal-index">{notes.map((note,i)=><button type="button" key={note.title} aria-pressed={journal===i} onClick={()=>setJournal(i)}>{note.title}</button>)}</div><Note lines={notes[Math.min(journal,notes.length-1)].lines}/></>:<p className="spring-aside">The notes you read will be kept here.</p>}</div>:<MapPuzzle state={state} controller={controller}/>}
  <div className="spring-save-information"><p>Progress saves in this browser. Papers and tools stay in your satchel.</p>{!confirmReset?<button type="button" onClick={()=>setConfirmReset(true)}>Start the trail again</button>:<div className="spring-reset-confirm"><p>This clears the trail discoveries on this browser. Your book reading position stays saved.</p><button type="button" onClick={()=>{controller.act('reset');try{localStorage.removeItem(FRAME_SAVE_KEY);}catch{}setConfirmReset(false);setTab('objects');}}>Yes, clear the trail</button><button type="button" onClick={()=>setConfirmReset(false)}>Keep my progress</button></div>}</div></>;
}

const HINTS:Partial<Record<SpringTarget,string[]>>={note:['The note mentions blue fabric and square glasses.','Open the rose-coloured door from the picnic side, then walk through.','Inside the classroom, find the blue cloth on the front desk. Inspect the plant, then the pouch on its open shelf.'],plant:['One of her gifts was alive.','Inspect the edge beneath the plant’s saucer.','Lift the saucer to take the envelope, then look on the desk shelf for the pouch.'],ticket:['The seat outline is split between the sleeves.','Turn the top sleeve and move it until both different corner marks coincide.','The top sleeve needs to return to its upright orientation and sit directly over the lower one. Use the arrows, then fold the sleeves together.'],tin:['There are raised lines beneath the tray.','Put paper over the lines, clip it to the thin rim, then rub it with the pencil.','The pouch at the school desk contains all three tools. Open the tin, lift the tray, place paper, add the clip and make five pencil strokes.'],bench:['The rubbing shows separate landmark sketches around the lake.','Close the drawing and follow the shore to find the tree with the forked trunk.','Look for a letter pocket at the roots of the forked cherry tree. It is marked on the drawing.'],lightbox:['No sheet shows the full pictures by itself.','Place each sheet and match the asymmetrical corner marks.','When all sheets sit upright over the frame, the pictures are sun, leaf and ripple, left to right.'],cabinet:['The setting comes from the light frame beside the cabinet.','Stack the three drawings and read their pictures from left to right.','Set the wheels to sun, leaf, ripple. Then slide the catch.'],map:['The instructions describe two pairs, rather than a path to walk.','Join the forked tree to the low stone, then the bridge to the paired stones.','Tap those pairs on the map. Their crossing is east of the garden rack, beyond the water.'],dig:['The earth is soft enough to work.','The garden rack holds a spade.','Take the spade, return to this patch and dig three times.'],box:['The lid has a small brass lock.','The matching key is in the school desk’s keepsake cabinet.','With the box out of the soil and the cabinet open, insert the key, turn it and lift the lid.']};

export function SpringTreasureUI({controller,target,onClose,onReadBook}:{controller:SpringTreasureController;target:SpringTarget|'satchel';onClose:()=>void;onReadBook:()=>boolean}){
  const state=useSyncExternalStore(controller.subscribe,controller.snapshot,controller.snapshot),[hint,setHint]=useState(0);
  const heading=useId(),shell=useRef<HTMLDivElement>(null),closeRef=useRef<HTMLButtonElement>(null),[title,location]=TITLES[target];
  useEffect(()=>{setHint(0);if(target==='note')controller.act('read-note');if(target==='phone')controller.act('read-phone');if(target==='cabinet'&&controller.state.cabinetOpen)controller.act('read-keepsakes');},[target,controller]);
  useEffect(()=>{const previous=document.activeElement as HTMLElement|null;closeRef.current?.focus();const onKey=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();onClose();}if(event.key==='Tab'){const focusable=Array.from(shell.current?.querySelectorAll<HTMLElement>('button:not([disabled]), [href], [tabindex="0"], summary')||[]).filter(el=>el.getClientRects().length>0);const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}};document.addEventListener('keydown',onKey,true);return()=>{document.removeEventListener('keydown',onKey,true);previous?.focus({preventScroll:true});};},[onClose]);
  let content:ReactNode;
  switch(target){
    case 'note':content=<div className="spring-first-letter"><span className="spring-letter-date">A few things I wanted you to find</span><Note lines={WORDS.opening}/><div className="spring-signature-line"/></div>;break;
    case 'plant':content=<div className="spring-puzzle-layout"><div><Note lines={WORDS.plant}/>{!state.plantFound?<Action onClick={()=>controller.act('lift-saucer')}>Lift the saucer carefully</Action>:<Status>The first ticket sleeve is in your satchel.</Status>}</div><div className="spring-plant-paper"><div className="spring-envelope-art"><span>For Aami</span></div>{state.plantFound?<Note lines={WORDS.envelope} small/>:<p className="spring-aside">An envelope edge peeks out beneath the pot.</p>}</div></div>;break;
    case 'pouch':content=<div className="spring-puzzle-layout"><div><Note lines={['Your hair clip is in here, along with a pencil and some tracing paper.','Keep them with you. You’ll need to make a copy of something later.']}/>{!state.pouchTaken?<Action onClick={()=>controller.act('take-pouch')}>Keep the pouch in your satchel</Action>:<Status>The clip, pencil and paper are safely with you.</Status>}</div><div className="spring-pouch-art"><span className="spring-pouch-pencil"/><span className="spring-pouch-clip"/><span className="spring-pouch-paper"/></div></div>;break;
    case 'phone':content=<div className="spring-puzzle-layout"><div><Note lines={WORDS.phone}/><p className="spring-aside">Written for this trail, remembering those early chats.</p></div><div className="spring-phone-art"><div className="spring-phone-speaker"/><span className="spring-phone-time">A message for today</span><div className="spring-phone-bubble">Keep the ticket sleeve. Its other half is waiting where we made room for two in one seat.</div><small>Shyamu</small></div></div>;break;
    case 'ticket':content=<TicketPuzzle state={state} controller={controller}/>;break;
    case 'tin':content=<TinPuzzle state={state} controller={controller}/>;break;
    case 'bench':content=<div className="spring-puzzle-layout"><div><Note lines={WORDS.lake} small/>{!state.benchVisited?<Action onClick={()=>controller.act('sit-bench')}>{state.rubbingDone?'Mark the forked tree on the rubbing':'Remember this lakeside view'}</Action>:<Status>Close the drawing, then follow the shore to find the forked tree.</Status>}</div><div className="spring-workspace">{state.rubbingDone?<><div className="spring-workspace-label">Drawing B · landmarks around the lake</div><LandscapeSketch mark={state.benchVisited}/><p className="spring-aside">The marked pocket is at the roots of the forked tree. Follow the path along the bank.</p></>:<><LandscapeSketch/><p className="spring-aside">The sweet tin at the bus stop holds the raised drawing. A rubbing of it will help you find the next letter.</p></>}</div></div>;break;
    case 'pocket':content=<div className="spring-puzzle-layout"><div><Note lines={WORDS.pocket}/>{!state.pocketFound?<Action onClick={()=>controller.act('take-drawing')}>Take drawing C from the envelope</Action>:<Status>Drawing C is safely in your satchel.</Status>}</div><div className="spring-found-sheet"><svg viewBox="0 0 400 220" aria-label="Drawing C, with corner marks and incomplete symbol fragments" role="img"><Registration/><SymbolFragments sheet={2}/></svg><span>C · found beside the forked tree</span></div></div>;break;
    case 'lightbox':content=<LightFrame state={state}/>;break;
    case 'cabinet':content=<Cabinet state={state} controller={controller}/>;break;
    case 'map':content=<MapPuzzle state={state} controller={controller}/>;break;
    case 'spade':content=<div className="spring-puzzle-layout"><div><p className="spring-object-description">A wooden-handled garden spade, standing in the rack. The edge of the blade is worn smooth.</p><Note lines={['You can borrow this for the patch of turned earth. Bring it with you.']} small/>{!state.spadeTaken?<Action onClick={()=>controller.act('take-spade')}>Take the garden spade</Action>:<Status>The spade is with you. You can use it at the soil patch.</Status>}</div><div className="spring-tool-portrait"><div className="spring-spade-silhouette"/></div></div>;break;
    case 'dig':content=<DigPuzzle state={state} controller={controller}/>;break;
    case 'box':content=<BoxPuzzle state={state} controller={controller} onReadBook={onReadBook}/>;break;
    case 'satchel':content=<Satchel state={state} controller={controller} onReadBook={onReadBook}/>;break;
  }
  return <div className="spring-inspection-backdrop" onPointerDown={event=>event.stopPropagation()} onTouchStart={event=>event.stopPropagation()}><div className="spring-inspection-shell" ref={shell} role="dialog" aria-modal="true" aria-labelledby={heading}><header className="spring-inspection-header"><div><span className="spring-location">{location}</span><h2 id={heading}>{title}</h2></div><button type="button" className="spring-close" onClick={onClose} ref={closeRef} aria-label="Close inspection and return to the grove"><span aria-hidden="true">×</span></button></header><div className="spring-inspection-body" key={target}>{content}</div><footer className="spring-inspection-footer"><div className="spring-hint-space">{target!=='satchel'&&HINTS[target]&&<><button type="button" className="spring-hint-button" onClick={()=>setHint(v=>Math.min(3,v+1))}>{hint?'A clearer nudge':'A little nudge'} <span aria-hidden="true">↗</span></button>{hint>0&&<p role="status">{HINTS[target]?.[hint-1]}</p>}</>}</div><button type="button" className="spring-return" onClick={onClose}>Back to exploring <span aria-hidden="true">↗</span></button></footer></div></div>;
}
